package com.studiocliquim.arquivos;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Bitmap;import android.view.*;import java.io.*;import java.nio.file.*;
public class UiSmokeTest extends Instrumentation {
 int checks=0;void ok(boolean pass,String label){if(!pass)throw new AssertionError(label);checks++;}
 void settle()throws Exception{MainActivity.IO.submit(()->{}).get();waitForIdleSync();Thread.sleep(300);}
 void shot(String name)throws Exception{Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap==null)throw new IOException("Screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();try{Context context=getTargetContext();MainActivity m=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));settle();runOnMainSync(()->{m.history.clear();m.welcome();ok(!m.newButton.isEnabled(),"new folder disabled on home");ok(!m.selectButton.isEnabled(),"selection disabled on home");ok(!m.findButton.isEnabled(),"search disabled on home");});settle();shot("ui-home");
 File fixture=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"Cliquim-UI-QA-"+System.currentTimeMillis());ok(fixture.mkdir(),"fixture");Files.write(new File(fixture,"Anotacoes.txt").toPath(),"Arquivo de teste".getBytes());Files.write(new File(fixture,"Relatorio.txt").toPath(),"Outro arquivo de teste".getBytes());ok(new File(fixture,"Referencias").mkdir(),"fixture folder");FileEngine.Node node=m.engine.local(fixture);runOnMainSync(()->m.navigate(node));settle();runOnMainSync(()->{ok(m.rows.size()==3,"actual files");ok(m.newButton.isEnabled(),"create enabled");ok(m.address.getText().toString().contains("Cliquim-UI-QA"),"real address");m.toggle(m.rows.get(0));ok(m.selected.size()==1,"selection");ok(m.editButton.isEnabled(),"actions enabled");});settle();shot("ui-selection");runOnMainSync(()->{m.back();ok(m.selected.isEmpty(),"back cancels selection");m.gridMode=true;m.render();ok(m.grid.getAdapter().getCount()==3,"grid count");});settle();shot("ui-grid");runOnMainSync(()->{m.gridMode=false;m.search.setText("Relatorio");ok(m.filtered().size()==1,"search actual match");m.search.setText("zzznothing");ok(m.filtered().isEmpty(),"search empty");m.search.setText("");m.dark=true;m.build();m.load();});settle();shot("ui-dark");runOnMainSync(()->{ok(m.panel==0xff202020,"dark background");m.dark=false;m.build();m.load();});settle();runOnMainSync(()->m.newFolder());settle();shot("ui-new-folder");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);settle();runOnMainSync(()->m.viewMenu());settle();shot("ui-menu");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);settle();ok(m.current.id.equals(node.id),"dialogs preserve folder");
 Bitmap fixtureImage=Bitmap.createBitmap(40,30,Bitmap.Config.ARGB_8888);fixtureImage.eraseColor(0xff008080);File photo=new File(fixture,"Imagem.png");try(FileOutputStream out=new FileOutputStream(photo)){fixtureImage.compress(Bitmap.CompressFormat.PNG,100,out);}fixtureImage.recycle();
 runOnMainSync(()->m.load());settle();FileEngine.Node imageNode=m.engine.local(photo);runOnMainSync(()->m.tap(imageNode));settle();runOnMainSync(()->{ok(m.preview!=null,"image opens internal preview");ok(m.preview.displayed!=null,"preview decoded asynchronously");ok(m.preview.displayed.getWidth()==40,"preview actual dimensions");ok(!m.findButton.isEnabled(),"folder search disabled in preview");});shot("ui-preview");
 runOnMainSync(()->m.back());settle();runOnMainSync(()->{ok(m.preview==null,"back closes preview");ok(m.rows.size()==4,"back restores folder");ok(m.findButton.isEnabled(),"folder actions restored");});
 java.util.concurrent.CountDownLatch blocked=new java.util.concurrent.CountDownLatch(1);MainActivity.IO.submit(()->{try{blocked.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});try{runOnMainSync(()->{m.load();m.welcome();});}finally{blocked.countDown();}settle();runOnMainSync(()->{ok(m.current==null&&m.rows.isEmpty(),"stale listing cannot replace home");ok(!m.prefs.contains("current"),"home does not restore old folder");});
 result.putString("stream","PASS "+checks+" UI checks, screenshots in app files. Fixture "+fixture.getName());finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL "+checks+": "+e);finish(Activity.RESULT_CANCELED,result);}}
}
